<?php $base = $type === 'holiday' ? '/admin/holiday-packages' : '/admin/tour-packages'; ?>
<div class="flex items-center justify-between mb-6"><h1 class="font-display font-extrabold text-2xl md:text-3xl text-brand-navy"><?= ucfirst($type) ?> Packages</h1><a href="<?= url($base.'/create') ?>" class="btn-accent px-4 py-2 rounded-lg text-sm font-semibold"><i class="fa-solid fa-plus mr-1"></i> Add Package</a></div>
<div class="bg-white rounded-xl shadow-sm border border-gray-100 overflow-x-auto"><table class="w-full text-sm"><thead class="bg-gray-50 text-left text-gray-600 text-xs uppercase tracking-wider"><tr><th class="p-3">Title</th><th>Destination</th><th>Duration</th><th>Price</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($packages as $p): ?><tr class="border-t hover:bg-gray-50"><td class="p-3 font-semibold"><?= htmlspecialchars($p['title']) ?><?php if (!empty($p['is_featured'])): ?> <span class="ml-1 text-[10px] bg-brand-red text-white px-1.5 py-0.5 rounded">FEATURED</span><?php endif; ?></td><td class="text-xs"><?= htmlspecialchars($p['destination_name'] ?? '-') ?></td><td class="text-xs"><?= (int)$p['duration_days'] ?>D/<?= (int)$p['duration_nights'] ?>N</td><td class="font-bold text-brand-red"><?= format_price((float)$p['price']) ?></td><td><?= !empty($p['is_active']) ? '<span class="text-green-600 text-xs font-bold">Active</span>' : '<span class="text-gray-400 text-xs">Inactive</span>' ?></td>
<td class="text-right text-xs"><a href="<?= url($base.'/'.$p['id'].'/edit') ?>" class="text-brand-navy font-semibold mr-2">Edit</a><form method="POST" action="<?= url($base.'/'.$p['id'].'/delete') ?>" data-confirm="Delete this package?" class="inline"><?= csrf_field() ?><button class="text-red-600 font-semibold">Delete</button></form></td></tr><?php endforeach; ?>
</tbody></table></div>
